function e(e){return e.split(`,`).map(e=>e.trim()+` *`).join(`,`)}function t(e){return e.split(`,`).join(`, `)}function n(e,t){let n=e.charCodeAt(t-1);return n>=55296&&n<=56319?t-1:t}function r(e,t){let n=e.charCodeAt(t);return n>=56320&&n<=57343?t+1:t}function i(e,t=256){if(e.length<=t)return e;let i=Math.floor((t-1)/3),a=t-1-i;return e.slice(0,n(e,a))+`…`+e.slice(r(e,e.length-i))}export{i as n,e as r,t};